// client/src/features/dashboard/attendee/AttendeeDashboard.jsx
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import '../../../styles/GlobalStyles.css';

const AttendeeDashboard = () => {
  const [events, setEvents]           = useState([]);
  const [registeredIds, setRegisteredIds] = useState([]);
  const [loading, setLoading]         = useState(true);
  const [error, setError]             = useState(null);

  // 1) fetch all events
  const fetchEvents = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('token');
      const res   = await axios.get('http://localhost:5000/api/attendee/events', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setEvents(res.data.events);
      setError(null);
    } catch {
      setError('Failed to fetch events');
    } finally {
      setLoading(false);
    }
  };

  // 2) fetch on mount
  useEffect(() => { fetchEvents(); }, []);

  // 3) register handler
  const handleRegister = async (eventId) => {
    try {
      const token = localStorage.getItem('token');
      await axios.post(
        'http://localhost:5000/api/attendee/register',
        { eventId },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setRegisteredIds(ids => [...ids, eventId]);
    } catch {
      alert('Registration failed');
    }
  };

  // split into upcoming vs registered
  const upcoming    = events.filter(e => !registeredIds.includes(e._id));
  const registered  = events.filter(e => registeredIds.includes(e._id));

  return (
    <div className="container">
      <div className="card">
        <h2>Attendee Dashboard</h2>

        {/* Upcoming Events */}
        <section>
          <h3>Upcoming Events</h3>
          {loading
            ? <p>Loading events…</p>
            : error
              ? <p style={{ color: 'red' }}>{error}</p>
              : upcoming.length > 0
                ? <ul>
                    {upcoming.map(evt => (
                      <li key={evt._id}>
                        <strong>{evt.title}</strong> | {new Date(evt.date).toLocaleString()}<br/>
                        <button
                          className="btn"
                          onClick={() => handleRegister(evt._id)}
                        >Register</button>
                      </li>
                    ))}
                  </ul>
                : <p>No upcoming events.</p>
          }
        </section>

        {/* Registered Events */}
        <section style={{ marginTop: '2rem' }}>
          <h3>Registered Events</h3>
          {registered.length > 0
            ? <ul>
                {registered.map(evt => (
                  <li key={evt._id}>
                    <strong>{evt.title}</strong> | {new Date(evt.date).toLocaleString()}<br/>
                    {/* later: show Pay & Join buttons here */}
                    <em>Registration confirmed</em>
                  </li>
                ))}
              </ul>
            : <p>You haven’t registered for any events yet.</p>
          }
        </section>
      </div>
    </div>
  );
};

export default AttendeeDashboard;
